CREATE TABLE public.admin_activity_notices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),message text NOT NULL,is_read boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,UPDATE ON public.admin_activity_notices TO authenticated; GRANT ALL ON public.admin_activity_notices TO service_role; ALTER TABLE public.admin_activity_notices ENABLE ROW LEVEL SECURITY; CREATE POLICY own_admin_notice_read ON public.admin_activity_notices FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.has_role(auth.uid(),'admin')); CREATE POLICY own_admin_notice_update ON public.admin_activity_notices FOR UPDATE TO authenticated USING(user_id=auth.uid() AND public.has_role(auth.uid(),'admin')) WITH CHECK(user_id=auth.uid() AND public.has_role(auth.uid(),'admin')); REVOKE UPDATE ON public.admin_activity_notices FROM authenticated; GRANT UPDATE(is_read) ON public.admin_activity_notices TO authenticated;
CREATE OR REPLACE FUNCTION public.notice_admin_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE actor uuid;label text;BEGIN IF TG_TABLE_NAME='messages' THEN actor:=NEW.sender_id;label:='కొత్త సందేశం నమోదైంది';ELSE actor:=NEW.user_id;label:=CASE WHEN TG_TABLE_NAME='posts' THEN 'కొత్త ప్రకటన నమోదైంది' ELSE 'ప్రకటనకు గంట నమోదైంది' END;END IF;INSERT INTO public.admin_activity_notices(user_id,message) SELECT user_id,label FROM public.user_roles WHERE role='admin' AND user_id<>actor;RETURN NEW;END $$;